import {SYSTEM_DEFAULTS,validateSystemInputs,parseSolarResource,simulateSystem} from './system-core.js';
const KEY='aimenergy.system-versions.v1';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=(x,d=0)=>x===null?'Not available':Number(x).toLocaleString('en-US',{maximumFractionDigits:d});
const money=x=>'$'+num(x,0);
const GROUPS=[['Equipment',[['pvKW','PV capacity','kWp'],['batteryKWh','Battery nominal energy','kWh'],['batteryKW','Battery AC power limit','kW'],['generatorKW','Generator limit','kW'],['roundTripEfficiency','Battery round-trip efficiency','fraction'],['fuelLitresPerKWh','Generator fuel intensity','litres/kWh']]],['Illustrative installed costs',[['pvCostPerKW','PV installed cost','USD/kWp'],['batteryCostPerKWh','Battery installed cost','USD/kWh'],['generatorCostPerKW','Generator installed cost','USD/kW'],['otherCapex','Other installed costs','USD'],['omPercent','Annual O&M','% of initial capex']]],['Illustrative financial assumptions',[['fuelPrice','Fuel price','USD/litre'],['tariff','Collected revenue per delivered kWh','USD/kWh'],['discountPercent','Real discount rate','%'],['years','Analysis horizon','years'],['replacementYear','Full battery replacement','year']]]];
let ctx,solar={resources:[]},draft={...SYSTEM_DEFAULTS},versions=[],snapshot=null,message='',memoryOnly=false;
const imports=new Map();
const site=()=>ctx.getSite();
const activeSnapshot=()=>snapshot?.siteId===String(site().id)?snapshot:null;
const demand=()=>{const d=activeSnapshot()?.demand||ctx.getDemand();return {monthly:d.monthly.slice(0,12)};};
const resource=()=>activeSnapshot()?.resource||imports.get(String(site().id))||solar.resources.find(r=>String(r.siteId)===String(site().id));
function clone(x){return JSON.parse(JSON.stringify(x));}
function download(name,data,type='application/json'){const u=URL.createObjectURL(new Blob([typeof data==='string'?data:JSON.stringify(data,null,2)],{type}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
function redraw(){ctx.render();}
export function initSystemLab(options,data){ctx=options;solar=data&&Array.isArray(data.resources)?data:{resources:[]};
  try{const raw=JSON.parse(localStorage.getItem(KEY)||'[]');if(!Array.isArray(raw)||raw.length>10)throw new Error();for(const v of raw){try{if(!v||v.schema!==1||typeof v.id!=='string'||v.id.length>80||typeof v.siteId!=='string'||typeof v.siteName!=='string'||v.siteName.length>150||!Number.isFinite(Date.parse(v.createdAt))||String(v.resource.siteId)!==v.siteId)throw new Error();const clean={schema:1,id:v.id,siteId:v.siteId,siteName:v.siteName,createdAt:new Date(v.createdAt).toISOString(),inputs:validateSystemInputs(v.inputs),demand:v.demand,resource:v.resource};simulateSystem(clean.demand,clean.resource,clean.inputs);versions.push(clean);}catch{message='Some invalid saved versions were skipped.';}}}catch{message='Saved system versions could not be read. You can still run and export a scenario.';memoryOnly=true;}
  document.addEventListener('submit',e=>{if(e.target.id!=='system-form')return;e.preventDefault();try{const form=new FormData(e.target);const values={};for(const key of Object.keys(SYSTEM_DEFAULTS)){const text=form.get(key);if(typeof text!=='string'||!text.trim())throw new Error('Complete every assumption before running.');values[key]=Number(text);}draft=validateSystemInputs(values);message='Scenario recalculated. Inputs remain illustrative assumptions.';redraw();}catch(err){document.querySelector('#system-message').textContent=err.message;}});
  document.addEventListener('click',e=>{const b=e.target.closest('[data-system]');if(b)action(b.dataset.system,b.dataset.id);});
  document.addEventListener('change',e=>{if(e.target.id==='system-solar-file')importSolar(e.target.files?.[0]);});
}
async function importSolar(file){if(!file)return;const capturedSite=clone(site());try{if(file.size>2_000_000)throw new Error('PVGIS JSON must be at most 2 MB.');const parsed=parseSolarResource(JSON.parse(await file.text()),capturedSite);parsed.source_file=file.name.slice(0,160);imports.set(String(capturedSite.id),parsed);if(String(site().id)===String(capturedSite.id)){snapshot=null;message='Matching PVGIS resource loaded locally for '+capturedSite.name+'. It is not uploaded or synchronized.';redraw();}}catch(err){message=err.message;redraw();}}
function action(action,id){try{message='';if(action==='pilot'){ctx.onPilot('5502954');snapshot=null;redraw();return;}
  if(action==='current'){snapshot=null;message='Using the current village demand scenario.';}
  if(action==='open'){const v=versions.find(v=>v.id===id&&v.siteId===String(site().id));if(v){snapshot=clone(v);draft=clone(v.inputs);message='Viewing a saved demand/resource snapshot. The village planner is unchanged.';}}
  const r=resource();
  if(['save','export','report'].includes(action)){const form=document.querySelector('#system-form');if(form){const values={};const data=new FormData(form);for(const key of Object.keys(SYSTEM_DEFAULTS)){const text=data.get(key);if(typeof text!=='string'||!text.trim())throw new Error('Complete every assumption.');values[key]=Number(text);}draft=validateSystemInputs(values);}if(!r)throw new Error('Load a matching solar resource first.');const d=demand(),result=simulateSystem(d,r,draft);const record={schema:1,id:crypto.randomUUID(),siteId:String(site().id),siteName:site().name,createdAt:new Date().toISOString(),inputs:clone(draft),demand:{monthly:d.monthly.slice(0,12).map(m=>({totalKWh:m.totalKWh,hourlyKW:[...m.hourlyKW]}))},resource:clone(r),scope:'Exploratory scenario, not optimized sizing, certified engineering or an investment recommendation.'};
    if(action==='save'){const next=[record,...versions].slice(0,10);try{localStorage.setItem(KEY,JSON.stringify(next));memoryOnly=false;message='Version saved on this browser. Latest 10 versions are retained across villages.';}catch{memoryOnly=true;message='Storage unavailable or full. Version retained in memory; export before leaving.';}versions=next;}
    if(action==='export')download('AimEnergy-system-scenario-'+site().id+'.json',{...record,result});
    if(action==='report')download('AimEnergy-system-report-'+site().id+'.html',report(record,result),'text/html');
  }
  redraw();}catch(err){message=err.message;redraw();}}
function sourceUrl(){const lat=Number(site().latitude??site().lat),lon=Number(site().longitude??site().lon);if(!Number.isFinite(lat)||!Number.isFinite(lon)||Math.abs(lat)>90||Math.abs(lon)>180)return null;return 'https://re.jrc.ec.europa.eu/api/v5_3/seriescalc?lat='+encodeURIComponent(lat)+'&lon='+encodeURIComponent(lon)+'&startyear=2023&endyear=2023&pvcalculation=1&peakpower=1&loss=14&angle=10&aspect=0&outputformat=json';}
function assumptions(){return '<form id="system-form">'+GROUPS.map(([label,fields])=>'<fieldset><legend>'+label+'</legend><div class="system-fields">'+fields.map(([key,label,unit])=>'<label>'+label+'<span>'+unit+'</span><input type="number" name="'+key+'" aria-label="'+label+'" value="'+esc(draft[key])+'" min="0" step="any" required></label>').join('')+'</div></fieldset>').join('')+'<button class="btn primary" type="submit">Run scenario</button></form>';}
function bars(rows){const max=Math.max(1,...rows.map(r=>r.demandKWh));return '<svg class="system-chart" viewBox="0 0 720 220" role="img" aria-label="Monthly demand split into simulated served and unmet energy">'+rows.map((m,i)=>{const x=25+i*57,h=m.demandKWh/max*160,unmet=m.unmetKWh/max*160;return '<rect x="'+x+'" y="'+(180-h)+'" width="30" height="'+h+'" rx="2" fill="#41694a"/><rect x="'+x+'" y="'+(180-h)+'" width="30" height="'+unmet+'" fill="#d79c5f"/><text x="'+(x+10)+'" y="205">'+(i+1)+'</text>';}).join('')+'</svg>';}
function resultHTML(out){const a=out.annual,e=out.economics;return '<div class="system-metrics">'+[['Demand served',a.demandKWh?num(a.servedKWh/a.demandKWh*100,1)+'%':'No demand'],['Unmet energy',num(a.unmetKWh)+' kWh'],['Generator fuel',num(a.fuelLitres)+' litres'],['Scenario LCOE',e.lcoe===null?'Not available':'$'+num(e.lcoe,3)+'/kWh'],['Scenario NPV',money(e.npv)],['Upfront cost',money(e.capex)]].map(([k,v])=>'<div><span>'+k+'</span><strong>'+v+'</strong></div>').join('')+'</div><section class="panel source-list"><div class="panel-head"><div><h2>Can this assumed system serve the scenario?</h2><p class="subtext">12 calendar months · green served, amber unmet · no daily/seasonal demand measurements</p></div></div>'+bars(out.monthly)+'<div class="table-wrap"><table class="data-table"><thead><tr><th>Month</th><th>Demand kWh</th><th>Served kWh</th><th>PV output kWh</th><th>Generator kWh</th><th>Unmet kWh</th></tr></thead><tbody>'+out.monthly.map(m=>'<tr><td>'+m.month+'</td>'+[m.demandKWh,m.servedKWh,m.pvKWh,m.generatorKWh,m.unmetKWh].map(x=>'<td>'+num(x)+'</td>').join('')+'</tr>').join('')+'</tbody></table></div></section><section class="panel source-list"><div class="panel-head"><h2>Energy and operating ledger</h2></div><div class="system-ledger">'+[['PV modeled output',a.pvKWh,'kWh'],['Battery charge at AC bus',a.batteryChargeKWh,'kWh'],['Battery delivered to AC bus',a.batteryDischargeKWh,'kWh'],['Curtailed PV',a.curtailedKWh,'kWh'],['Final stored energy (20% floor included)',a.endingStoredKWh,'kWh'],['Hours with unmet load',a.unmetHours,'hours'],['Annual operating cost',e.annualOperatingCost,'USD'],['Annual collected revenue assumption',e.annualRevenue,'USD']].map(([k,v,u])=>'<div><span>'+k+'</span><strong>'+num(v,1)+' '+u+'</strong></div>').join('')+'</div><div class="meter-body"><p>Battery charges from PV surplus only; generator serves residual load up to its limit. SOC is bounded to 20–95% of nominal capacity, starts at the minimum, and charge/discharge power limits are measured at the AC bus. Battery energy is an intermediate flow, not additional generation.</p><details><summary>Assumptions and excluded effects</summary><ul>'+out.warnings.map(w=>'<li>'+esc(w)+'</li>').join('')+'</ul><p>Grid import/export, battery ageing, generator starts/minimum loading, surge, distribution losses, protection, cable/network design, taxes, debt, salvage and equipment optimization are excluded. No single-line diagram or engineering certification is produced.</p></details></div></section>';}
function report(record,out){const a=out.annual,e=out.economics;return '<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>AimEnergy system scenario</title><style>body{font:15px/1.6 system-ui;max-width:950px;margin:40px auto;padding:20px;color:#173c34}table{width:100%;border-collapse:collapse}th,td{padding:8px;text-align:left;border-bottom:1px solid #ddd}.note{padding:16px;background:#f2f4e8}pre{white-space:pre-wrap;overflow-wrap:anywhere}@media print{button{display:none}body{margin:0}}</style><h1>AimEnergy · system feasibility scenario</h1><p>'+esc(record.siteName)+' · '+esc(record.createdAt)+'</p><p class="note">Exploratory, assumption-driven simulation. Not optimized equipment sizing, certified engineering, a lender-ready report or an investment recommendation. Use the browser Print / Save as PDF command to create a PDF.</p><h2>Annual results</h2><p>Demand '+num(a.demandKWh)+' kWh; served '+num(a.servedKWh)+'; unmet '+num(a.unmetKWh)+'. Generator fuel '+num(a.fuelLitres)+' litres. Upfront cost '+money(e.capex)+'. LCOE '+(e.lcoe===null?'not available':'$'+num(e.lcoe,3)+'/kWh')+'; NPV '+money(e.npv)+'.</p><h2>Solar resource</h2><p>'+esc(record.resource.source)+' · '+record.resource.year+' · '+esc(record.resource.timezone)+'</p><h2>Equipment and cost assumptions</h2><pre>'+esc(JSON.stringify(record.inputs,null,2))+'</pre><h2>Cashflow assumptions</h2><p>All costs and revenue are illustrative, constant real USD. First-year dispatch repeats over the financial horizon, with battery replacement in the selected year if it falls within the analysis horizon. Collected tariff is applied only to delivered energy. No actual cost quotes, collection performance or commercial return is established.</p><table><thead><tr><th>Year</th><th>Cost USD</th><th>Revenue USD</th><th>Net USD</th></tr></thead><tbody>'+e.cashflows.map(y=>'<tr><td>'+y.year+'</td><td>'+num(y.cost)+'</td><td>'+num(y.revenue)+'</td><td>'+num(y.net)+'</td></tr>').join('')+'</tbody></table><h2>Limits</h2><ul>'+out.warnings.map(w=>'<li>'+esc(w)+'</li>').join('')+'</ul><p>Grid, degradation, detailed fuel curves, cable/network design, protection, taxes, debt and engineering verification are excluded. Demand follows scenario assumptions, not metered observations. Download the JSON scenario for the complete hourly ledger.</p></html>';}
export function renderSystemLab(){const s=site(),r=resource(),url=sourceUrl();let out=null,error='';try{if(r)out=simulateSystem(demand(),r,draft);}catch(e){error=e.message;}
  return '<div class="view-heading"><h2>From demand to a system scenario.</h2><p>'+esc(s.name)+' · inspect an hourly energy balance before commissioning detailed engineering.</p></div><div class="info-note"><strong>Exploratory feasibility, with visible assumptions.</strong> This is an hourly PV / battery / generator scenario, not automated equipment sizing or an investor-ready engineering design. Costs are illustrative USD assumptions.</div><div class="system-source panel"><div><span class="head-tag">'+(r?'SOLAR RESOURCE LOADED':'SOLAR RESOURCE NEEDED')+'</span><h3>'+esc(r?r.source:'Load a matching PVGIS resource')+'</h3><p>'+(r?esc(r.year)+' · '+num(r.hourlyKWhPerKWp.length)+' hourly samples · '+esc(r.timezone):'The acquired satellite-derived solar example covers Orii Gangodye. Other sites need their own matching PVGIS JSON. No unrelated village resource is silently substituted.')+'</p></div><div class="system-source-actions">'+(!r?'<button class="btn" data-system="pilot">Open Orii Gangodye example</button>':'')+(url?'<a class="btn" href="'+esc(url)+'" target="_blank" rel="noopener noreferrer">Open site PVGIS JSON</a>':'')+'<label class="btn system-upload">Load PVGIS JSON<input id="system-solar-file" type="file" accept=".json,application/json"></label></div></div>'+(activeSnapshot()?'<div class="info-note">Saved demand/resource snapshot · '+esc(snapshot.createdAt)+'. Editing assumptions creates a working copy; the saved version and village planner stay unchanged. <button class="btn" data-system="current">Use current village demand</button></div>':'')+'<div class="system-layout"><section class="panel system-assumptions"><h3>Choose an assumption set</h3><p>Defaults are examples, not recommendations. Changing these fields does not change demand in the village planner.</p>'+assumptions()+'</section><div class="system-results"><p id="system-message" role="status">'+esc(error||message)+'</p>'+(out?resultHTML(out):'<div class="remote-empty"><h3>No result without a matching resource.</h3><p>Open the acquired pilot example or load a complete non-leap-year PVGIS file for this site. Location checks prevent cross-site substitution.</p></div>')+'</div></div><section class="panel source-list"><div class="panel-head"><div><h2>Keep the assumptions with the result</h2><p class="subtext">Versions are saved on this browser, not to an account. '+(memoryOnly?'Storage unavailable: export before leaving.':'Latest 10 local versions retained across villages.')+'</p></div></div><div class="system-actions"><button class="btn" data-system="save" '+(!out?'disabled':'')+'>Save local version</button><button class="btn" data-system="export" '+(!out?'disabled':'')+'>Export full scenario JSON</button><button class="btn" data-system="report" '+(!out?'disabled':'')+'>Export print-ready report</button></div><div class="system-versions">'+versions.filter(v=>v.siteId===String(s.id)).map(v=>'<button class="btn" data-system="open" data-id="'+esc(v.id)+'">View '+esc(new Date(v.createdAt).toLocaleString())+'</button>').join('')+'</div></section><p class="control-help">PVGIS is modeled solar/PV output, not measured demand or generation. Acquired reference: fixed 10° south-facing c-Si, 14% system losses already included. The annual hourly demand follows the first 12 scenario months and repeated normalized daily timing; financial years repeat this first-year result. Solar year boundaries use a disclosed cyclic UTC+3 approximation. There is no automatic cloud sync or live site-resource API in the static demo.</p>';}
